// Deploy identity: what a running Worker may claim about the build and the
// deployment event that put it live.
//
// Two halves, never mixed. The build stamp (src/build-stamp.ts, generated by
// ci/deploy-identity.mjs before the single compile) carries the source SHA,
// the build ID and the input-set digest, so the same bytes carry the same
// stamp in every environment. The environment deploy event ID
// (`YYYY.MM.DD.N+sha7`) and the GitHub Deployment ID are attached to one
// Worker Version as non-secret runtime bindings together with
// `CF_VERSION_METADATA.id`; they are never compiled.
//
// `deployIdentity` is the single decision behind `GET /version` and
// `GET /readyz`. It returns the fixed five-field allowlist only when every
// piece agrees, and otherwise a bare refusal with no identity field, so a
// missing, malformed or contradictory input can never become a success claim.
import { buildShaFromTag } from "./release-tag";

export type BuildStamp = { sourceSha: string; buildId: string; inputSetDigest: string };

export type DeployIdentity = {
  source_sha: string;
  build_id: string;
  deploy_event_id: string;
  github_deployment_id: string;
  cloudflare_version_id: string;
};

export type DeployIdentityInput = {
  stamp: unknown;
  deployEventId: unknown;
  deploymentEnvironment: unknown;
  githubDeploymentId: unknown;
  cfVersionMetadata: { id?: unknown; tag?: unknown } | null | undefined;
};

export type DeployIdentityResult = { ok: true; identity: DeployIdentity } | { ok: false };

export type DeployEventId = { date: string; sequence: number; sha7: string };

const EVENT_ID = /^(\d{4})\.(\d{2})\.(\d{2})\.([1-9]\d{0,5})\+([0-9a-f]{7})$/;
const SOURCE_SHA = /^[0-9a-f]{40}$/;
const BUILD_ID = /^[1-9]\d{0,19}-[1-9]\d{0,19}-[1-9]\d{0,19}$/;
const INPUT_DIGEST = /^[0-9a-f]{64}$/;
const GITHUB_DEPLOYMENT_ID = /^[1-9]\d{0,19}$/;
const VERSION_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const ENVIRONMENTS = new Set(["staging", "production"]);

function isRealDate(year: number, month: number, day: number): boolean {
  const probe = new Date(0);
  probe.setUTCFullYear(year, month - 1, day);
  return (
    probe.getUTCFullYear() === year &&
    probe.getUTCMonth() === month - 1 &&
    probe.getUTCDate() === day
  );
}

/**
 * Parse a canonical deploy event ID: a real zero-padded UTC calendar date, a
 * positive sequence of at most six digits without leading zeros and a
 * lowercase 7-hex short SHA. No trimming or case folding; anything else is null.
 */
export function parseDeployEventId(value: unknown): DeployEventId | null {
  if (typeof value !== "string") return null;
  const match = EVENT_ID.exec(value);
  if (!match) return null;
  const [, year, month, day, sequence, sha7] = match as unknown as [
    string,
    string,
    string,
    string,
    string,
    string,
  ];
  if (!isRealDate(Number(year), Number(month), Number(day))) return null;
  return { date: `${year}.${month}.${day}`, sequence: Number(sequence), sha7 };
}

/** The exact three-field build stamp, or null for any other shape (extra fields refuse). */
export function validateBuildStamp(value: unknown): BuildStamp | null {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return null;
  // Exactly three fields, each validated below, so any extra field refuses.
  if (Object.keys(value).length !== 3) return null;
  const { sourceSha, buildId, inputSetDigest } = value as Record<string, unknown>;
  if (typeof sourceSha !== "string" || !SOURCE_SHA.test(sourceSha)) return null;
  if (typeof buildId !== "string" || !BUILD_ID.test(buildId)) return null;
  if (typeof inputSetDigest !== "string" || !INPUT_DIGEST.test(inputSetDigest)) return null;
  return { sourceSha, buildId, inputSetDigest };
}

/**
 * The fail-closed identity decision. Only the named input fields are read, so
 * stamp-shaped extras on the input object can never override the compiled stamp.
 * An absent or unparseable Version tag is tolerated (the tag surface keeps its
 * existing tolerance); a parseable one must name the stamped commit.
 */
export function deployIdentity(input: DeployIdentityInput): DeployIdentityResult {
  const stamp = validateBuildStamp(input.stamp);
  if (!stamp) return { ok: false };
  const event = parseDeployEventId(input.deployEventId);
  if (!event || event.sha7 !== stamp.sourceSha.slice(0, 7)) return { ok: false };
  const environment = input.deploymentEnvironment;
  if (typeof environment !== "string" || !ENVIRONMENTS.has(environment)) return { ok: false };
  const deploymentId = input.githubDeploymentId;
  if (typeof deploymentId !== "string" || !GITHUB_DEPLOYMENT_ID.test(deploymentId)) {
    return { ok: false };
  }
  const versionId = input.cfVersionMetadata?.id;
  if (typeof versionId !== "string" || !VERSION_UUID.test(versionId)) return { ok: false };
  const taggedSha = buildShaFromTag(input.cfVersionMetadata?.tag);
  if (taggedSha !== null && taggedSha !== stamp.sourceSha) return { ok: false };
  return {
    ok: true,
    identity: {
      source_sha: stamp.sourceSha,
      build_id: stamp.buildId,
      deploy_event_id: input.deployEventId as string,
      github_deployment_id: deploymentId,
      cloudflare_version_id: versionId,
    },
  };
}
